negatives=['How much does a flight from Sydney cost today?','What is the capital of Argentina?','Explain plate tectonics at a subduction zone.','What is the recipe for sourdough bread?','Who won the latest football final?','How should I tune a violin?','Explain DNA transcription in a cell.','How do lunar tides form?','What is the boiling point of ethanol?','How do I renew my passport?','How many satellites does Mars have?','What is the derivative of sine?']
rows=[]
for i,(fact,a,b) in enumerate(facts):rows.extend([{'question':a,'expected':i,'split':'validation'},{'question':b,'expected':i,'split':'heldout'}])
for i,q in enumerate(negatives):rows.append({'question':q,'expected':None,'split':'validation' if i%2==0 else 'heldout'})
pathlib.Path(__file__).with_name('corpus.json').write_text(json.dumps({'documents':[f[0] for f in facts],'queries':rows},indent=2)+'\n')
